{ pkgs, lib, config, ... }:
let
  greet = name: "Hello ${name}";
  script = ''echo "${pkgs.hello}/bin/hello"; echo ''${HOME}'';
  custom = x: x;
in rec {
  imports = [ ./hardware-configuration.nix ];
  environment.systemPackages = with pkgs; [ hello git ];
  home.file."config".text = script;
  enabled = true;
  value = builtins.map greet [ "Ada" ];
  result = custom "argument";
  check = config ? services.sshd.enable;
  default = config.value or null;
  packages = pkgs // { inherit greet; };
}
